struct Team {
    name: &'static str,
    solved: u32,
    penalty: u32,
    last_accept: u32,
}

fn main() {
    let mut teams = vec![
        Team { name: "Ivy", solved: 7, penalty: 430, last_accept: 90 },
        Team { name: "Zoe", solved: 6, penalty: 350, last_accept: 80 },
        Team { name: "Ada", solved: 7, penalty: 410, last_accept: 95 },
        Team { name: "Moe", solved: 7, penalty: 410, last_accept: 102 },
        Team { name: "Eli", solved: 7, penalty: 410, last_accept: 95 },
    ];

    teams.sort_by(|a, b| {
        b.solved
            .cmp(&a.solved)
            .then(a.penalty.cmp(&b.penalty))
            .then(a.last_accept.cmp(&b.last_accept))
            .then(a.name.cmp(&b.name))
    });

    let mut prev: Option<(u32, u32, u32)> = None;
    let mut display_rank = 0usize;
    for t in teams.iter() {
        let key = (t.solved, t.penalty, t.last_accept);
        if prev != Some(key) {
            display_rank += 1;
            prev = Some(key);
        }
        println!(
            "{}. {} solved={} penalty={} last={}",
            display_rank, t.name, t.solved, t.penalty, t.last_accept
        );
    }
}

