            tags: None,
        };

        let merged = merge_config(&base(), &env, &cli);
        assert_eq!(merged.host, "cli.example.com");
        assert_eq!(merged.port, 9443);
        assert!(merged.tls);
        assert_eq!(merged.timeout_ms, 3500);
        assert_eq!(merged.retries, 1);
    }

    #[test]
